test("calculates the weighted final grade from category scores", function () {
  var result = code.finalGrade({ homework: [90, 80, 70, 100], quizzes: [80, 70], exam: [60] });
  assert.equal(result.homeworkAverage, 90);
  assert.equal(result.quizAverage, 75);
  assert.equal(result.examScore, 60);
  assert.equal(result.droppedHomework, 70);
  assert.equal(result.final, 70.5);
  assert.equal(result.display, "70.5");
});

test("averages fewer than four homework scores and drops none", function () {
  var result = code.finalGrade({ homework: [90, 80, 70], quizzes: [80, 70], exam: [60] });
  assert.equal(result.homeworkAverage, 80);
  assert.equal(result.quizAverage, 75);
  assert.equal(result.examScore, 60);
  assert.equal(result.droppedHomework, null);
  assert.equal(result.final, 68.5);
  assert.equal(result.display, "68.5");
});

test("drops only one homework score when the lowest score is tied", function () {
  var result = code.finalGrade({ homework: [70, 70, 80, 90], quizzes: [100], exam: [100] });
  assert.equal(result.homeworkAverage, 80);
  assert.equal(result.quizAverage, 100);
  assert.equal(result.examScore, 100);
  assert.equal(result.droppedHomework, 70);
  assert.equal(result.final, 96.0);
  assert.equal(result.display, "96.0");
});

test("averages every quiz score and does not drop the lowest quiz", function () {
  var result = code.finalGrade({ homework: [100], quizzes: [40, 60, 80, 100], exam: [80] });
  assert.equal(result.homeworkAverage, 100);
  assert.equal(result.quizAverage, 70);
  assert.equal(result.examScore, 80);
  assert.equal(result.droppedHomework, null);
  assert.equal(result.final, 81.0);
  assert.equal(result.display, "81.0");
});

test("counts no quiz scores as zero", function () {
  var result = code.finalGrade({ homework: [90, 80, 70, 100], quizzes: [], exam: [60] });
  assert.equal(result.homeworkAverage, 90);
  assert.equal(result.quizAverage, 0);
  assert.equal(result.examScore, 60);
  assert.equal(result.droppedHomework, 70);
  assert.equal(result.final, 48.0);
  assert.equal(result.display, "48.0");
});

test("counts no homework scores as zero", function () {
  var result = code.finalGrade({ homework: [], quizzes: [80, 70], exam: [60] });
  assert.equal(result.homeworkAverage, 0);
  assert.equal(result.quizAverage, 75);
  assert.equal(result.examScore, 60);
  assert.equal(result.droppedHomework, null);
  assert.equal(result.final, 52.5);
  assert.equal(result.display, "52.5");
});

test("counts a missing exam score as zero", function () {
  var result = code.finalGrade({ homework: [90, 80, 70, 100], quizzes: [80, 70], exam: [] });
  assert.equal(result.homeworkAverage, 90);
  assert.equal(result.quizAverage, 75);
  assert.equal(result.examScore, 0);
  assert.equal(result.droppedHomework, 70);
  assert.equal(result.final, 40.5);
  assert.equal(result.display, "40.5");
});

test("rounds a final grade that is not an exact half to one decimal", function () {
  var result = code.finalGrade({ homework: [80, 80, 85], quizzes: [70, 71], exam: [77] });
  assert.equal(result.homeworkAverage, (80 + 80 + 85) / 3);
  assert.equal(result.quizAverage, 70.5);
  assert.equal(result.examScore, 77);
  assert.equal(result.droppedHomework, null);
  assert.equal(result.final, 76.0);
  assert.equal(result.display, "76.0");
});

test("throws when the input has an unknown field", function () {
  assert.throws(function () {
    code.finalGrade({ homework: [90], quizzes: [80], exam: [60], bonus: 1 });
  }, /^unknown field: bonus$/);
});
